        case 10:
            //none
            break;
        case 15:
            create_object(allObjects[object_index].position.x, allObjects[object_index].position.y, 0, 0, explosion, 0, 0);
            create_object(allObjects[object_index].position.x, allObjects[object_index].position.y, 0, 0, flame, 0, 0);
