void player_bolt_burst_step(int obj) {
    play_sound_on_player(snd_super_splinter_ID);
    for (int S = 0; S < 2; S++) {
        float inaccuracy = (random_float(10.0f * 2.0f) - 10.0f) / degreestoradians;
        float proj_speed = random_float(4.0f) + 20.0f;
        float Xspd = cos(direction_to_mouse + inaccuracy) * proj_speed;
        float Yspd = sin(direction_to_mouse + inaccuracy) * proj_speed;
        create_object(allObjects[0].position.x + Xspd / 8, allObjects[0].position.y + Yspd / 8, Xspd, Yspd, player_bolt, direction_to_mouse + inaccuracy, 3);
    }
    allObjects[obj].size--;
    if (allObjects[obj].size <= 0) {
        allObjects[obj].my_id = nothing;
    }
}

void player_bullet_burst_step(int obj) {
    float inaccuracy = 0.0f;
    float inaccuracy_x = 0.0f;
    float inaccuracy_y = 0.0f;
    if (allObjects[obj].image_index % allObjects[obj].alarm1 == 0) {
        if (allObjects[obj].alarm2 != 2) {
            int IIDX = 0;
            if (allObjects[obj].damage == 3) {
                IIDX = 0;   //normal
            }
            else {
                IIDX = 3;   //heavy
            }

            allObjects[obj].size--;

            if (allObjects[obj].damage == 3) {
                if (allObjects[obj].alarm2 == 0) {
                    if (allObjects[obj].alarm1 != 1) {
                        play_sound_on_player(snd_machinegun_ID);
                        inaccuracy = random_float(2.0f) - 1.0f;
                    }
                    else {//hyper rifle
                        play_sound_on_player(snd_hyper_rifle_ID);
                        inaccuracy = random_float(2.0f) - 1.0f;
                    }
                }
                else {
                    play_sound_on_player(snd_gold_machinegun_ID);
                    inaccuracy = random_float(2.0f) - 1.0f;
                }
            }
            else {
                play_sound_on_player(snd_heavy_machinegun_ID);
                inaccuracy = 0.0f;
            }
            inaccuracy /= degreestoradians;
            inaccuracy_x = cos(direction_to_mouse + inaccuracy) * 16.0f;
            inaccuracy_y = sin(direction_to_mouse + inaccuracy) * 16.0f;
            create_object(allObjects[0].position.x + inaccuracy_x / 4, allObjects[0].position.y + inaccuracy_y / 4, inaccuracy_x, inaccuracy_y, player_bullet, direction_to_mouse + inaccuracy, IIDX);
            if (wep == 33 || wep == 38 || wep == 43 || wep == 46) {
                wep_kick = 4;
            }
        }
        else {  //rogue burst
            allObjects[obj].size--;
            play_sound_on_player(snd_rogue_rifle_ID);
            inaccuracy = random_float(10.0f) - 5.0f;
            inaccuracy /= degreestoradians;
            inaccuracy_x = cos(direction_to_mouse + inaccuracy) * 16.0f;
            inaccuracy_y = sin(direction_to_mouse + inaccuracy) * 16.0f;
            create_object(allObjects[0].position.x + inaccuracy_x / 4, allObjects[0].position.y + inaccuracy_y / 4, inaccuracy_x, inaccuracy_y, rogue_bullet, direction_to_mouse + inaccuracy, 0);
            if (wep == 31) {
                wep_kick = 4;
            }
        }
    }
    allObjects[obj].image_index++;
    if (allObjects[obj].size <= 0) {
        allObjects[obj].my_id = nothing;
    }
}

void player_explosive_burst_step(int obj) {
    float inaccuracy = 0.0f;
    float inaccuracy_x = 0.0f;
    float inaccuracy_y = 0.0f;
    if ((allObjects[obj].image_index % allObjects[obj].alarm2) == 0) {
        if (allObjects[obj].damage == 3) {//nade rifle

            allObjects[obj].alarm1--;
            play_sound_on_player(snd_grenade_rifle_ID);
            inaccuracy = random_float(8.0f) - 4.0f;
            inaccuracy /= degreestoradians;

            create_object(allObjects[0].position.x, allObjects[0].position.y, 13.0f + random_float(2.0f), 0, nade, direction_to_mouse + inaccuracy, 1);

            if (wep == 92) {
                wep_kick = 5;
            }
        }
        else if (allObjects[obj].damage == 4) {  //flamethrower
            allObjects[obj].alarm1--;
            player_shot_flamethrower_this_frame = true;
            for (int i = 0; i < 2; i++) {
                inaccuracy = random_float(10.0f) - 5.0f;
                inaccuracy /= degreestoradians;
                
                float tmp_spd = 6.0f + random_float(2.0f);

                inaccuracy_x = cos(direction_to_mouse + inaccuracy) * tmp_spd;
                inaccuracy_y = sin(direction_to_mouse + inaccuracy) * tmp_spd;

                //player_flame
                create_object(allObjects[0].position.x + inaccuracy_x / 2 + random_float(4) - 2, allObjects[0].position.y + inaccuracy_y / 2 + random_float(4) - 2, inaccuracy_x, inaccuracy_y, player_flame, direction_to_mouse + inaccuracy, 0);
            }
            if (wep == 103) {
                wep_kick = 2;
            }
        }
        else if (allObjects[obj].damage == 5) {  //dragon
            allObjects[obj].alarm1--;
            player_shot_dragon_this_frame = true;
            for (int j = -1; j < 2; j++) {
                for (int i = 0; i < 2; i++) {
                    inaccuracy = random_float(10.0f) - 5.0f + j * 8.0f;
                    inaccuracy /= degreestoradians;

                    float tmp_spd = 9.0f + random_float(3.0f) + float(j == 0);

                    inaccuracy_x = cos(direction_to_mouse + inaccuracy) * tmp_spd;
                    inaccuracy_y = sin(direction_to_mouse + inaccuracy) * tmp_spd;

                    //player_flame
                    create_object(allObjects[0].position.x + inaccuracy_x / 2 + random_float(4) - 2, allObjects[0].position.y + inaccuracy_y / 2 + random_float(4) - 2, inaccuracy_x, inaccuracy_y, player_flame, direction_to_mouse + inaccuracy, 0);
                }
            }
            if (wep == 104) {
                wep_kick = 4;
            }
        }
        else if (allObjects[obj].damage == 6) {  //jackhammer //TODO
            allObjects[obj].alarm1--;
            play_sound_on_player(snd_jackhammer_ID);

                    inaccuracy = random_float(30.0f) - 15.0f;
                    inaccuracy /= degreestoradians;

                    //player_shank
                    swing_shank(direction_to_mouse + inaccuracy, 0.0f, 6.0f);

            if (wep == 109) {
                wep_kick = -8;
            }
        }
    }
    allObjects[obj].image_index++;
    if (allObjects[obj].alarm1 <= 0) {
        allObjects[obj].my_id = nothing;
    }
}

