void check_character_selection_screen(bool clicked, bool right_clicked) {
    
    if (character_hovered_over != go_button) {
        go_button_hover_frames = 0;
    }
    character_hovered_over_prev_frame = character_hovered_over;
    option_hovered_over_prev_frame = option_hovered_over;
    //hover over
    character_hovered_over = none_character;
    option_hovered_over = none_option;
    setting_hovered_over = 0;
    if (current_frame > 5) {
        //right click logic
        if (right_clicked) {
            if (option_in != settings_option || options_menu_IN == pick_settings || options_menu_IN == none_options_menu) {
                options_menu_IN = none_options_menu;
                option_in = none_option;
                options_text_frame = 0;

                setting_hovered_over = 0;
                setting_hovered_over_prev = 0;
                setting_hovered_over_time = 0;
                options_menu_splat_frame = 0;
            }
            else if (options_menu_IN == audio_settings || options_menu_IN == video_settings || options_menu_IN == controls_settings) {
                options_menu_IN = pick_settings;
                option_in = settings_option;
                options_text_frame = 0;

                setting_hovered_over = 0;
                setting_hovered_over_prev = 0;
                setting_hovered_over_time = 0;
                options_menu_splat_frame = 0;
            }
        }
        //options selection
        if (mousepos.y > 4 && mousepos.y < 4 + 26) {
            if (mousepos.x > 320 - 23 && mousepos.x < 320 - 5) {
                option_hovered_over = settings_option;
                if (clicked) {
                    options_menu_IN = pick_settings;
                    option_in = settings_option;
                    options_text_frame = 0;

                    setting_hovered_over = 0;
                    setting_hovered_over_prev = 0;
                    setting_hovered_over_time = 0;
                    options_menu_splat_frame = 0;
                }
            }
            if (mousepos.x > 320 - 23 * 2 && mousepos.x < 320 - 5 - 23) {
                option_hovered_over = stats_option;
                if (clicked) {
                    options_menu_IN = stats_settings;
                    option_in = stats_option;
                    options_text_frame = 0;

                    setting_hovered_over = 0;
                    setting_hovered_over_prev = 0;
                    setting_hovered_over_time = 0;
                    options_menu_splat_frame = 0;
                }
            }
            if (mousepos.x > 320 - 23 * 3 && mousepos.x < 320 - 5 - 23 * 2) {
                option_hovered_over = leaderboard_option;
                if (clicked) {
                    options_menu_IN = leaderboard_settings;
                    option_in = leaderboard_option;
                    options_text_frame = 0;

                    setting_hovered_over = 0;
                    setting_hovered_over_prev = 0;
                    setting_hovered_over_time = 0;
                    options_menu_splat_frame = 0;
                }
            }
            if (mousepos.x > 320 - 23 * 4 && mousepos.x < 320 - 5 - 23 * 3) {
                option_hovered_over = credits_option;
                if (clicked) {
                    options_menu_IN = credits_settings;
                    option_in = credits_option;
                    options_text_frame = 0;

                    setting_hovered_over = 0;
                    setting_hovered_over_prev = 0;
                    setting_hovered_over_time = 0;
                    options_menu_splat_frame = 0;
                }
            }
        }
        //different options menus
        
        if (options_menu_IN == pick_settings) {
            if (mousepos.x > 180 && mousepos.x < 180 + 115) {
                if (mousepos.y > 100 && mousepos.y < 100 + 25) {
                    setting_hovered_over = 1;
                    if (clicked) {
                        options_menu_IN = audio_settings;
                        options_text_frame = 0;

                        setting_hovered_over = 0;
                        setting_hovered_over_prev = 0;
                        setting_hovered_over_time = 0;
                        options_menu_splat_frame = 0;
                    }
                }
                else if (mousepos.y > 100 + 25 && mousepos.y < 100 + 50) {
                    setting_hovered_over = 2;
                    if (clicked) {
                        options_menu_IN = video_settings;
                        options_text_frame = 0;

                        setting_hovered_over = 0;
                        setting_hovered_over_prev = 0;
                        setting_hovered_over_time = 0;
                        options_menu_splat_frame = 0;
                    }
                }
                else if (mousepos.y > 100 + 50 && mousepos.y < 100 + 75) {
                    setting_hovered_over = 3;
                    if (clicked) {
                        options_menu_IN = controls_settings;
                        options_text_frame = 0;

                        setting_hovered_over = 0;
                        setting_hovered_over_prev = 0;
                        setting_hovered_over_time = 0;
                        options_menu_splat_frame = 0;
                    }
                }
            }
        }
        
        //character selection
        if (mousepos.y > 240 - 31 && mousepos.y < 240 - 7) {
            int x_off = mousepos.x - 6;
            if (x_off < 0) {
                x_off = 0;
            }
            int x = (x_off) / 19;
            if ((x_off) % 19 < 16 && mousepos.x - 6 > 0 && x < 14) {
                character_hovered_over = character(x);
            }

            if (mousepos.x > 320 - 47 && mousepos.x < 320 - 4) {
                character_hovered_over = go_button;
                go_button_hover_frames++;
            }
            else {
                go_button_hover_frames = 0;
            }
        }
        if (clicked) {
            if ((character_selected == character_hovered_over || (character_hovered_over == go_button && character_selected != none_character)) && character_hovered_over != none_character) {
                START_RUN = true;
                go_button_appear_frame = 0;
                play_character_confirm_sound();
                
            }
            if (character_hovered_over != none_character && character_hovered_over != go_button) {
                character_selected = character_hovered_over;
                character_text_desc_offset = 3;
                play_character_select_sound();
            }
        }

        if (character_selected != none_character) {
            go_button_appear_frame++;
        }
    }
}

sf::Color HSV_to_RGB(int hue, int sat, int val) {
    double      hh, p, q, t, ff;
    long        i;
    sf::Color   out;

    double inh = double(hue) / 255.0 * 360.0;
    double inv = double(val) / 255.0;
    double ins = double(sat) / 255.0;

    hh = inh;
    if (hh >= 360.0) hh = 0.0;
    hh /= 60.0;
    i = (long)hh;
    ff = hh - i;
    p = inv * (1.0 - ins);
    q = inv * (1.0 - (ins * ff));
    t = inv * (1.0 - (ins * (1.0 - ff)));

    switch (i) {
    case 0:
        out.r = uint8_t(inv * 255.0);
        out.g = uint8_t(t * 255.0);
        out.b = uint8_t(p * 255.0);
        break;
    case 1:
        out.r = uint8_t(q * 255.0);
        out.g = uint8_t(inv * 255.0);
        out.b = uint8_t(p * 255.0);
        break;
    case 2:
        out.r = uint8_t(p * 255.0);
        out.g = uint8_t(inv * 255.0);
        out.b = uint8_t(t * 255.0);
        break;

    case 3:
        out.r = uint8_t(p * 255.0);
        out.g = uint8_t(q * 255.0);
        out.b = uint8_t(inv * 255.0);
        break;
    case 4:
        out.r = uint8_t(t * 255.0);
        out.g = uint8_t(p * 255.0);
        out.b = uint8_t(inv * 255.0);
        break;
    case 5:
    default:
        out.r = uint8_t(inv * 255.0);
        out.g = uint8_t(p * 255.0);
        out.b = uint8_t(q * 255.0);
        break;
    }
    return out;
}

