            current_music.play();
            break;
        case 5:
            current_music.openFromFile("mus/mus5.ogg");
            current_music.setVolume(100.0f);
            current_music.play();
            break;
        case 6:
            current_music.openFromFile("mus/mus6.ogg");
            current_music.setVolume(100.0f);
            current_music.play();
            break;
        case 7:
            current_music.openFromFile("mus/mus7.ogg");
